-- =====================================================================
--  GATE PASS SYSTEM — Supabase schema + seed
--  Team / iisang database / walang login.
--  I-paste ang buong file na ito sa Supabase → SQL Editor → Run.
-- =====================================================================

create extension if not exists "pgcrypto";

-- ---------- Tables ----------
create table if not exists public.records (
  id             uuid primary key default gen_random_uuid(),
  control        text default '',
  label          text default '',
  person         text default '',
  purpose        text default '',
  items          jsonb not null default '[]'::jsonb,
  requested_by   text default '',
  requested_date text default '',
  authorized_by  text default '',
  authorized_date text default '',
  status         text default 'draft',
  sort_key       text default '',
  released_at    timestamptz,
  returned_at    timestamptz,
  created_at     timestamptz default now(),
  updated_at     timestamptz default now()
);

create table if not exists public.inventory (
  id          uuid primary key default gen_random_uuid(),
  description  text not null default '',
  serial       text default '',
  unit         text default '1',
  created_at   timestamptz default now()
);

create table if not exists public.people (
  id        uuid primary key default gen_random_uuid(),
  name      text not null,
  position  text default ''
);

create table if not exists public.app_settings (
  id         text primary key default 'default',
  data       jsonb not null default '{}'::jsonb,
  updated_at timestamptz default now()
);

create table if not exists public.counters (
  name  text primary key,
  value integer not null default 0
);
insert into public.counters (name, value) values ('control', 0)
  on conflict (name) do nothing;

-- ---------- Atomic control-number generator ----------
create or replace function public.next_control(p_prefix text default '')
returns text
language plpgsql
security definer
set search_path = public
as $$
declare v_num int; v_year text;
begin
  update public.counters set value = value + 1
    where name = 'control'
    returning value into v_num;
  v_year := to_char(now(), 'YYYY');
  return coalesce(p_prefix,'') || v_year || '-' || lpad(v_num::text, 3, '0');
end;
$$;

-- ---------- Grants + RLS (walang login: bukas sa anon key) ----------
grant usage on schema public to anon, authenticated;
grant all on all tables in schema public to anon, authenticated;
grant execute on function public.next_control(text) to anon, authenticated;

alter table public.records      enable row level security;
alter table public.inventory    enable row level security;
alter table public.people       enable row level security;
alter table public.app_settings enable row level security;
alter table public.counters     enable row level security;

do $$ begin
  create policy anon_all_records   on public.records      for all to anon, authenticated using (true) with check (true);
  create policy anon_all_inventory on public.inventory    for all to anon, authenticated using (true) with check (true);
  create policy anon_all_people    on public.people       for all to anon, authenticated using (true) with check (true);
  create policy anon_all_settings  on public.app_settings for all to anon, authenticated using (true) with check (true);
  create policy anon_all_counters  on public.counters     for all to anon, authenticated using (true) with check (true);
exception when duplicate_object then null; end $$;


